insert into assortment_items (id, organization_id, product_id, shop_name, farmer_description, region, category, name, product_description, url_product, url_farmer, price, stock, monthly_sales) values
(153240, 10060, 153240, 'Экоферма ОГО-РОД', 'Выращиваем фрукты и ягоды в Подмосковье.Наша ферма располагается в деревне Лукино Серпуховского района. В нашем распоряжении 3 га земли, в будущем планируем засадить большую часть этого пространства яблоневыми деревьями. На данный момент у нас уже растет более 300 яблонь, а также кусты малины, смородины, ежевики. Мы очень бережно относимся к нашим яблоням, из плодов которых создаем натуральные продукты для вас. Наша ферма также предоставляет возможность для агротуризма, где все желающие могут побыть наедине с природой, а также узнать много нового об уходе за растениями.', 'Москва', 'Бакалея', 'Зеленый чай "Японская липа"', 'Ароматный чай, в составе которого только натуральные ингредиенты, что делает его не только вкусным, но и полезным. Наш чай - замечательный способ расслабиться, забыть на время о проблемах и заботах, наслаждаясь насыщенным вкусом. Также может стать отличным подарком, который придется по душе каждому.', 'https://svoe-rodnoe.ru/category/organicheskie-produkty/10060-11123456-zelenyj-chaj-japonskaja-lipa', 'https://svoe-rodnoe.ru/farmers/10060', 541.00, 79, 10),
(170407, 10060, 170407, 'Экоферма ОГО-РОД', 'Выращиваем фрукты и ягоды в Подмосковье.Наша ферма располагается в деревне Лукино Серпуховского района. В нашем распоряжении 3 га земли, в будущем планируем засадить большую часть этого пространства яблоневыми деревьями. На данный момент у нас уже растет более 300 яблонь, а также кусты малины, смородины, ежевики. Мы очень бережно относимся к нашим яблоням, из плодов которых создаем натуральные продукты для вас. Наша ферма также предоставляет возможность для агротуризма, где все желающие могут побыть наедине с природой, а также узнать много нового об уходе за растениями.', 'Москва', 'Бакалея', 'Иван-чай сибирский 50 гр', 'Считается, что именно натуральный иван-чай без вкусовых добавок обладает "тем самым" нежным, ласковым и неповторимым вкусом, за который он так полюбился ценителям чая. Кроме того, иван-чай оказывает благотворное воздействие на организм, так же поможет расслабится после утомительного рабочего дня. Состав: иван-чай сибирский Условия хранения: Хранить в сухом, проветриваемом помещении при относительно влажности не более 70%. Отдельно от остро пахнущий продуктов. Срок годности: 24 месяца.', 'https://svoe-rodnoe.ru/category/chai-i-travy/10060-000-ivan-chaj-sibirskij-50-gr', 'https://svoe-rodnoe.ru/farmers/10060', 401.00, 192, 83),
(126752, 10060, 126752, 'Экоферма ОГО-РОД', 'Выращиваем фрукты и ягоды в Подмосковье.Наша ферма располагается в деревне Лукино Серпуховского района. В нашем распоряжении 3 га земли, в будущем планируем засадить большую часть этого пространства яблоневыми деревьями. На данный момент у нас уже растет более 300 яблонь, а также кусты малины, смородины, ежевики. Мы очень бережно относимся к нашим яблоням, из плодов которых создаем натуральные продукты для вас. Наша ферма также предоставляет возможность для агротуризма, где все желающие могут побыть наедине с природой, а также узнать много нового об уходе за растениями.', 'Москва', 'Бакалея', 'Смесь семян для салата', 'Наш продукт представляет собой смесь семян после отжима масла (т.е. жмых). В жмыхе содержится большое количество витаминов, микро-, макроэлементов, а также клетчатка. Он также обладает очищающим свойством кишечника и даёт чувство сытости. Смесь семян придаёт блюду неповторимый пикантный вкус свежих семян. Продукт полностью натуральный и готов к употреблению. Мы советуем использовать для овощных салатов в сочетании с нашими сыродавленными маслами и яблочным уксусом для полного раскрытия вкуса.', 'https://svoe-rodnoe.ru/category/superfudy-i-semena/10060-14-smes-semjan-dlja-salata', 'https://svoe-rodnoe.ru/farmers/10060', 751.00, 96, 86),
(153258, 10060, 153258, 'Экоферма ОГО-РОД', 'Выращиваем фрукты и ягоды в Подмосковье.Наша ферма располагается в деревне Лукино Серпуховского района. В нашем распоряжении 3 га земли, в будущем планируем засадить большую часть этого пространства яблоневыми деревьями. На данный момент у нас уже растет более 300 яблонь, а также кусты малины, смородины, ежевики. Мы очень бережно относимся к нашим яблоням, из плодов которых создаем натуральные продукты для вас. Наша ферма также предоставляет возможность для агротуризма, где все желающие могут побыть наедине с природой, а также узнать много нового об уходе за растениями.', 'Москва', 'Бакалея', 'Травяной сбор "Гречишный чай"', 'Откройте для себя уникальный вкус и пользу для здоровья с нашим гречишным чаем! Этот напиток, приготовленный из обжаренных зерен татарской гречихи, станет настоящим открытием для тех, кто заботится о своем самочувствии и стремится к здоровому образу жизни. Гречишный чай обладает насыщенным, слегка ореховым вкусом и приятным ароматом обжаренного зерна. Он не содержит кофеина, поэтому идеально подходит для употребления в любое время дня, особенно вечером, когда хочется расслабиться и отдохнуть. Помимо своего неповторимого вкуса, гречишный чай является ценным источником антиоксидантов, витаминов и минералов. Он способствует укреплению иммунитета, улучшению пищеварения, снижению уровня холестерина и нормализации артериального давления. Благодаря высокому содержанию рутина, гречишный чай полезен для здоровья сосудов и сердца. Выращено без использования химических удобрений и пестицидов.', 'https://svoe-rodnoe.ru/category/organicheskie-produkty/10060-122345678-travjanoj-sbor-grechishnyj-chaj', 'https://svoe-rodnoe.ru/farmers/10060', 297.00, 251, 76),
(153259, 10060, 153259, 'Экоферма ОГО-РОД', 'Выращиваем фрукты и ягоды в Подмосковье.Наша ферма располагается в деревне Лукино Серпуховского района. В нашем распоряжении 3 га земли, в будущем планируем засадить большую часть этого пространства яблоневыми деревьями. На данный момент у нас уже растет более 300 яблонь, а также кусты малины, смородины, ежевики. Мы очень бережно относимся к нашим яблоням, из плодов которых создаем натуральные продукты для вас. Наша ферма также предоставляет возможность для агротуризма, где все желающие могут побыть наедине с природой, а также узнать много нового об уходе за растениями.', 'Москва', 'Бакалея', 'Травяной сбор "Лаванда цветы"', 'Окунитесь в мир спокойствия и ароматерапии с нашими нежными цветками лаванды. Собранные вручную в период их максимального цветения и бережно высушенные, они сохранили свой неповторимый, успокаивающий аромат и насыщенный фиолетовый цвет. Лаванда также прекрасно подходит для приготовления ароматного чая, который успокаивает нервную систему и помогает справиться с тревожностью. А еще, вы можете использовать цветки лаванды в кулинарии, добавляя их в выпечку, десерты или напитки, чтобы придать им неповторимый вкус и аромат. Мы заботимся о Вашем здоровье, поэтому каждая упаковка наполнена отборными цветками лаванды, выращенными без использования химических удобрений и пестицидов.', 'https://svoe-rodnoe.ru/category/organicheskie-produkty/10060-123345678-travjanoj-sbor-lavanda-cvety', 'https://svoe-rodnoe.ru/farmers/10060', 894.00, 192, 74),
(153260, 10060, 153260, 'Экоферма ОГО-РОД', 'Выращиваем фрукты и ягоды в Подмосковье.Наша ферма располагается в деревне Лукино Серпуховского района. В нашем распоряжении 3 га земли, в будущем планируем засадить большую часть этого пространства яблоневыми деревьями. На данный момент у нас уже растет более 300 яблонь, а также кусты малины, смородины, ежевики. Мы очень бережно относимся к нашим яблоням, из плодов которых создаем натуральные продукты для вас. Наша ферма также предоставляет возможность для агротуризма, где все желающие могут побыть наедине с природой, а также узнать много нового об уходе за растениями.', 'Москва', 'Бакалея', 'Травяной сбор "Мята лист"', 'Наши сушеные листья мяты – это универсальный ингредиент для создания освежающих напитков, ароматных блюд и расслабляющих ванн. Заварите чашку мятного чая, чтобы взбодриться утром, успокоить нервы вечером или облегчить пищеварение после еды. Добавьте мяту в лимонад, коктейль или смузи, чтобы придать им яркий и освежающий вкус. Мята также широко используется в кулинарии. Она прекрасно сочетается с мясными блюдами, салатами, десертами и выпечкой, добавляя им нотку свежести и оригинальности. Ароматные мятные ванны помогут снять усталость, расслабить мышцы и улучшить сон. Наша мяты выращена без использования химических удобрений и пестицидов, чтобы вы могли наслаждаться только самым чистым и натуральным продуктом.', 'https://svoe-rodnoe.ru/category/organicheskie-produkty/10060-123445678-travjanoj-sbor-mjata-list', 'https://svoe-rodnoe.ru/farmers/10060', 252.00, 40, 74),
(153261, 10060, 153261, 'Экоферма ОГО-РОД', 'Выращиваем фрукты и ягоды в Подмосковье.Наша ферма располагается в деревне Лукино Серпуховского района. В нашем распоряжении 3 га земли, в будущем планируем засадить большую часть этого пространства яблоневыми деревьями. На данный момент у нас уже растет более 300 яблонь, а также кусты малины, смородины, ежевики. Мы очень бережно относимся к нашим яблоням, из плодов которых создаем натуральные продукты для вас. Наша ферма также предоставляет возможность для агротуризма, где все желающие могут побыть наедине с природой, а также узнать много нового об уходе за растениями.', 'Москва', 'Бакалея', 'Травяной сбор "Ромашка головки"', 'Заварите чашку ароматного ромашкового чая, чтобы расслабиться после тяжелого дня, создать уютную атмосферу перед сном или просто насладиться моментом тишины и покоя. Ромашка обладает сильным успокаивающим свойством, благотворно влияет на нервную систему, помогает бороться с бессонницей. Ромашка также может использоваться в качестве натурального средства для ухода за кожей, смягчая и успокаивая раздражения. В каждой упаковке – тщательно отобранные головки ромашки, выращенные без использования химических удобрений и пестицидов, чтобы подарить вам только самое лучшее от природы.', 'https://svoe-rodnoe.ru/category/organicheskie-produkty/10060-123455678-travjanoj-sbor-romashka-golovki', 'https://svoe-rodnoe.ru/farmers/10060', 617.00, 41, 87),
(153255, 10060, 153255, 'Экоферма ОГО-РОД', 'Выращиваем фрукты и ягоды в Подмосковье.Наша ферма располагается в деревне Лукино Серпуховского района. В нашем распоряжении 3 га земли, в будущем планируем засадить большую часть этого пространства яблоневыми деревьями. На данный момент у нас уже растет более 300 яблонь, а также кусты малины, смородины, ежевики. Мы очень бережно относимся к нашим яблоням, из плодов которых создаем натуральные продукты для вас. Наша ферма также предоставляет возможность для агротуризма, где все желающие могут побыть наедине с природой, а также узнать много нового об уходе за растениями.', 'Москва', 'Бакалея', 'Травяной чай "Коноплянка"', 'Ароматный чай, в составе которого только натуральные ингредиенты, что делает его не только вкусным, но и полезным. Наш чай - замечательный способ расслабиться, забыть на время о проблемах и заботах, наслаждаясь насыщенным вкусом. Также может стать отличным подарком, который придется по душе каждому.', 'https://svoe-rodnoe.ru/category/organicheskie-produkty/10060-12345677-fruktovyj-chaj-konopljanka', 'https://svoe-rodnoe.ru/farmers/10060', 534.00, 25, 18),
(170405, 10060, 170405, 'Экоферма ОГО-РОД', 'Выращиваем фрукты и ягоды в Подмосковье.Наша ферма располагается в деревне Лукино Серпуховского района. В нашем распоряжении 3 га земли, в будущем планируем засадить большую часть этого пространства яблоневыми деревьями. На данный момент у нас уже растет более 300 яблонь, а также кусты малины, смородины, ежевики. Мы очень бережно относимся к нашим яблоням, из плодов которых создаем натуральные продукты для вас. Наша ферма также предоставляет возможность для агротуризма, где все желающие могут побыть наедине с природой, а также узнать много нового об уходе за растениями.', 'Москва', 'Бакалея', 'Уксус из морошки 200 мл', 'Наш уксус из морошки произведён из свежих ягод без добавления сахара, консервантов, красителей, усилителей вкуса, ароматизаторов и любых других химических компонентов. Несмотря на то, что морошка довольно дорогая, она обладает богатым составом, который по пользе превосходит многие привычные фрукты и ягоды. Польза уксуса из морошки: - в 4 раза больше витамина С, чем в апельсинах + редкий витамин Е в составе - природный антисептик, защищающий от простуд и инфекций - антиоксиданты в составе морошки борются с оксидативным стрессом, что оказывает лёгкий антивозрастной эффект - помогает восполнить дефицит железа и витаминов (A, B, C) Состав: морошка, артезианская вода, мёд Срок годности: 12 месяцев Условия хранения: от 2°С до 25°С в темном месте. Допускается выпадение остатка и образование уксусной матки', 'https://svoe-rodnoe.ru/category/grocery/10060-0000-uksus-iz-moroshki-200-ml', 'https://svoe-rodnoe.ru/farmers/10060', 939.00, 117, 41),
(170404, 10060, 170404, 'Экоферма ОГО-РОД', 'Выращиваем фрукты и ягоды в Подмосковье.Наша ферма располагается в деревне Лукино Серпуховского района. В нашем распоряжении 3 га земли, в будущем планируем засадить большую часть этого пространства яблоневыми деревьями. На данный момент у нас уже растет более 300 яблонь, а также кусты малины, смородины, ежевики. Мы очень бережно относимся к нашим яблоням, из плодов которых создаем натуральные продукты для вас. Наша ферма также предоставляет возможность для агротуризма, где все желающие могут побыть наедине с природой, а также узнать много нового об уходе за растениями.', 'Москва', 'Бакалея', 'Уксус из черноплодной рябины 500 мл', 'Наш уксус из черноплодной рябины произведён из свежих ягод без добавления сахара, консервантов, красителей, усилителей вкуса, ароматизаторов и любых других химических компонентов. Польза уксуса из черноплодной рябины: - высокое содержание антиоксидантов, витаминов С, Р, группы В, йода и флавоноидов - рутин в составе снижает ломкость капилляров, нормализует давление - является природным щитом против вирусов за счет высокой дозы витамина С - мягко стимулирует пищеварение и выработку ферментов Состав: черноплодная рябина, артезианская вода, мёд Срок годности: 12 месяцев Условия хранения: от 2°С до 25°С в темном месте. Допускается выпадение остатка и образование уксусной матки', 'https://svoe-rodnoe.ru/category/grocery/10060-99-uksus-iz-chernoplodnoj-rjabiny-500-ml', 'https://svoe-rodnoe.ru/farmers/10060', 698.00, 192, 20),
(156606, 10060, 156606, 'Экоферма ОГО-РОД', 'Выращиваем фрукты и ягоды в Подмосковье.Наша ферма располагается в деревне Лукино Серпуховского района. В нашем распоряжении 3 га земли, в будущем планируем засадить большую часть этого пространства яблоневыми деревьями. На данный момент у нас уже растет более 300 яблонь, а также кусты малины, смородины, ежевики. Мы очень бережно относимся к нашим яблоням, из плодов которых создаем натуральные продукты для вас. Наша ферма также предоставляет возможность для агротуризма, где все желающие могут побыть наедине с природой, а также узнать много нового об уходе за растениями.', 'Москва', 'Бакалея', 'Уксус яблочный', 'Наш яблочный уксус произведен из натуральных свежих яблок (сорта Лигол, Хани крисп, Карамельная, Антоновка) без добавления сахара, консервантов, красителей, усилителей вкуса, ароматизаторов и любых других химических компонентов.', 'https://svoe-rodnoe.ru/category/organicheskie-produkty/10060-44565667-uksus-jablochnyj', 'https://svoe-rodnoe.ru/farmers/10060', 1216.00, 136, 41),
